#include "display/gauge_renderer.h"
#include <cstdio>
#include "core/gauge_geometry.h"
#include "config/speedbike_config.h"
namespace { constexpr int16_t Cx=148,Cy=124; void text(IndexedCanvas &c,const char*s,int16_t x,int16_t y,uint8_t z,uint16_t color){int16_t x1,y1;uint16_t w,h;c.setFont();c.setTextSize(z);c.getTextBounds(s,0,y,&x1,&y1,&w,&h);c.setTextColor(color);c.setCursor(x-w/2-x1,y);c.print(s);} }
void drawGauge(IndexedCanvas &c,uint16_t needle,uint16_t readout,bool noData){c.fillScreen(TftColor::Background);for(float d=150;d<=390;d+=.5f){const uint16_t color=d>=rpmToAngleDegrees(10000)?TftColor::RedDim:TftColor::CyanDim;const auto a=pointOnArc(Cx,Cy,98,d);const auto b=pointOnArc(Cx,Cy,106,d);c.drawLine(a.x,a.y,b.x,b.y,color);}for(uint16_t rpm=0;rpm<=12000;rpm+=500){const bool major=rpm%1000==0;const uint16_t color=rpm>=10000?TftColor::Red:TftColor::Cyan;const float d=rpmToAngleDegrees(rpm);const auto a=pointOnArc(Cx,Cy,major?82:92,d);const auto b=pointOnArc(Cx,Cy,106,d);c.drawLine(a.x,a.y,b.x,b.y,color);if(major){const auto p=pointOnArc(Cx,Cy,68,d);char label[3];snprintf(label,sizeof label,"%u",rpm/1000);text(c,label,p.x,p.y+6,2,rpm>=10000?TftColor::Red:TftColor::Text);c.drawLine(a.x+1,a.y,b.x+1,b.y,color);}}const float d=rpmToAngleDegrees(needle);const auto tip=pointOnArc(Cx,Cy,94,d);const auto left=pointOnArc(Cx,Cy,7,d-90);const auto right=pointOnArc(Cx,Cy,7,d+90);c.fillTriangle(tip.x,tip.y,left.x,left.y,right.x,right.y,needle>=10000?TftColor::Red:TftColor::Cyan);c.fillCircle(Cx,Cy,8,TftColor::Text);if(noData)text(c,"SEM DADOS",Cx,172,2,TftColor::Muted);else{char value[6];snprintf(value,sizeof value,"%u",readout);text(c,value,Cx,164,4,TftColor::Text);}text(c,"RPM",Cx,206,2,TftColor::Muted);}
